package br.com.marealta.mail;

import java.time.ZoneId;
import java.util.Map;

/**
 * Combinação de regras de mensagem de uma instalação. Cada regra tem um {@link Scope}.
 * O redirecionamento do modo de teste não é configurável: sempre vale em modo de teste.
 */
public record MailSettings(
        boolean testMode,
        Scope addressValidation,
        Scope archiveCopy,
        Scope quietHours,
        Scope dailyLimit,
        int quietStartHour,
        int quietEndHour,
        int dailyLimitMax,
        String archiveAddress,
        String testAddress,
        ZoneId zone) {

    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";

    /** Padrão da pousada: validação sempre, cópia para o arquivo fora do teste, sem horário nem limite. */
    public static MailSettings defaults(boolean testMode) {
        return new MailSettings(testMode, Scope.ALWAYS, Scope.LIVE_ONLY, Scope.OFF, Scope.OFF,
                22, 7, 5, ARCHIVE_ADDRESS, TEST_ADDRESS, ZoneId.of("America/Sao_Paulo"));
    }

    public static MailSettings fromEnv(Map<String, String> env) {
        boolean test = "true".equalsIgnoreCase(env.getOrDefault("HOTEL_TEST_MODE", "").trim());
        MailSettings d = defaults(test);
        return new MailSettings(
                test,
                Scope.parse(env.get("HOTEL_MAIL_VALIDATION"), d.addressValidation),
                Scope.parse(env.get("HOTEL_MAIL_ARCHIVE_COPY"), d.archiveCopy),
                Scope.parse(env.get("HOTEL_MAIL_QUIET_HOURS"), d.quietHours),
                Scope.parse(env.get("HOTEL_MAIL_DAILY_LIMIT"), d.dailyLimit),
                intOf(env.get("HOTEL_MAIL_QUIET_START"), d.quietStartHour),
                intOf(env.get("HOTEL_MAIL_QUIET_END"), d.quietEndHour),
                intOf(env.get("HOTEL_MAIL_DAILY_LIMIT_MAX"), d.dailyLimitMax),
                env.getOrDefault("HOTEL_MAIL_ARCHIVE_ADDRESS", d.archiveAddress),
                env.getOrDefault("HOTEL_MAIL_TEST_ADDRESS", d.testAddress),
                env.get("HOTEL_ZONE") == null ? d.zone : ZoneId.of(env.get("HOTEL_ZONE")));
    }

    private static int intOf(String raw, int fallback) {
        return raw == null || raw.isBlank() ? fallback : Integer.parseInt(raw.trim());
    }
}
EOF
cat > MessagePolicy.java <<'EOF'
package br.com.marealta.mail;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;

/**
 * Decide o que realmente é guardado/enviado para uma mensagem desejada:
 * 1) regras de bloqueio (endereço inválido, madrugada, limite diário);
 * 2) redirecionamento do modo de teste;
 * 3) cópia para o arquivo.
 */
public final class MessagePolicy {
    private final MailSettings s;

    public MessagePolicy(MailSettings settings) {
        this.s = settings;
    }

    /** @param sentToday quantas mensagens já foram enviadas hoje ao endereço original dado */
    public List<Outgoing> apply(String to, String subject, String body, Instant now, ToIntFunction<String> sentToday) {
        List<Outgoing> out = new ArrayList<>();
        if (isBlocked(to, now, sentToday)) {
            out.add(new Outgoing(to, subject, body, Outgoing.BLOCKED, to));
            return out;
        }
        String finalTo = to, finalSubject = subject, finalBody = body;
        if (s.testMode()) {
            finalTo = s.testAddress();
            finalSubject = "[TESTE] " + subject;
            finalBody = "Destinatário original: " + to + "\n" + body;
        }
        out.add(new Outgoing(finalTo, finalSubject, finalBody, Outgoing.SENT, to));
        if (s.archiveCopy().applies(s.testMode())) {
            out.add(new Outgoing(s.archiveAddress(), "[Cópia] " + finalSubject, finalBody, Outgoing.SENT, null));
        }
        return out;
    }

    private boolean isBlocked(String to, Instant now, ToIntFunction<String> sentToday) {
        boolean test = s.testMode();
        if (s.addressValidation().applies(test) && !isValidAddress(to)) return true;
        if (s.quietHours().applies(test) && inQuietHours(now)) return true;
        return s.dailyLimit().applies(test) && sentToday.applyAsInt(to) >= s.dailyLimitMax();
    }

    private boolean inQuietHours(Instant now) {
        int h = now.atZone(s.zone()).getHour();
        int a = s.quietStartHour(), b = s.quietEndHour();
        return a <= b ? (h >= a && h < b) : (h >= a || h < b);
    }

    /** Um único @, algo antes dele e, depois, um nome com pelo menos um ponto no meio. */
    public static boolean isValidAddress(String address) {
        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
        int at = address.indexOf('@');
        if (at <= 0 || at != address.lastIndexOf('@')) return false;
        String domain = address.substring(at + 1);
        int dot = domain.indexOf('.');
        return dot > 0 && domain.lastIndexOf('.') < domain.length() - 1 && !domain.isEmpty();
    }
}
EOF

